import { expect, test, uniqueName } from "../../fixtures";

const TEN_MIB = 10 * 1024 * 1024;

const cases = [
  { name: "an empty file", kind: "w9", status: 422, code: "empty_file", file: { name: "w9.txt", mimeType: "text/plain", buffer: Buffer.alloc(0) } },
  { name: "a file of exactly 10 MiB + 1", kind: "w9", status: 413, code: "file_too_large", file: { name: "big.txt", mimeType: "text/plain", buffer: Buffer.alloc(TEN_MIB + 1, "x") } },
  { name: "a \".exe\" file", kind: "w9", status: 415, code: "unsupported_type", file: { name: "tool.exe", mimeType: "application/octet-stream", buffer: Buffer.from("MZ") } },
  { name: "a valid text file", kind: "passport", status: 422, code: "validation_error", file: { name: "notes.txt", mimeType: "text/plain", buffer: Buffer.from("valid text") } },
];

test.describe("upload vendor documents", () => {
  for (const c of cases) {
    test(`rejects ${c.name} as kind "${c.kind}" with ${c.status} ${c.code}`, { tag: "@DOC-04" }, async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const vendorRes = await member.post("/api/vendors", {
        data: {
          name: uniqueName("Doc Vendor"),
          category: "software",
          contact_email: `ops+${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}@vendor-intake.com`,
        },
      });
      expect(vendorRes.status(), await vendorRes.text()).toBe(201);
      const vendor = await vendorRes.json();

      // Act
      const res = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: { kind: c.kind, file: c.file },
      });

      // Assert
      const body = await res.text();
      expect(res.status(), body).toBe(c.status);
      const error = JSON.parse(body).error ?? JSON.parse(body);
      expect(error.code ?? error.detail?.[0]?.type, body).toBe(c.code);
    });
  }
});
